ily: \'Heebo\', sans-serif !important;\n    font-weight: bold !important;\n    transition: 0.3s !important;\n}\n.search-submit:hover {\n    box-shadow: 0 5px 15px rgba(0,208,132,0.4) !important;\n}</p>\n<p>/* Hide theme default titles if they mess up layout */\n.site-title, .site-description { display: none !important; }\n</style>\n<p><script>\n// Small script to clean up header layout if needed\ndocument.addEventListener(\'DOMContentLoaded\', function() {\n    var header = document.querySelector(\'#masthead\') || document.querySelector(\'.site-header\');\n    if(header) {\n        var wrap = header.querySelector(\'.site-header-wrapper\') || header.querySelector(\'.container\');\n        if(wrap) {\n            wrap.style.display = \'flex\';\n            wrap.style.width = \'100%\';\n            wrap.style.justifyContent = \'space-between\';\n            wrap.style.alignItems = \'center\';\n            wrap.style.flexDirection = \'row-reverse\';\n        }\n    }\n});\n</script></p>\n<style>\n/* Force Full Width */\n#sidebar, .sidebar, aside, #secondary { display: none !important; }\n#primary, #content, .site-main, .content-area, .entry-content { \n    width: 100% !important; max-width: 100% !important; float: none !important; margin: 0 !important; padding: 0 !important; border: none !important; \n}\n.site-content { display: block !important; padding: 0 !important; max-width: 1200px !important; margin: 0 auto !important; }</p>\n<p>.energi-page-bg {\n    background: radial-gradient(circle at 10% 20%, rgba(0, 208, 132, 0.15) 0%, transparent 40%),\n                radial-gradient(circle at 90% 80%, rgba(44, 62, 80, 0.1) 0%, transparent 40%),\n                #f8fafc;\n    padding: 40px 20px;\n    border-radius: 20px;\n}\n.energi-glass-card {\n    background: rgba(255, 255, 255, 0.35);\n    backdrop-filter: blur(20px);\n    -webkit-backdrop-filter: blur(20px);\n    border: 1px solid rgba(255,255,255,0.6);\n    border-radius: 24px;\n    padding: 40px;\n    box-shadow: 0 