  background: #2C3E50;\n    color: white;\n    border-radius: 50%;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    cursor: pointer;\n    box-shadow: 0 4px 15px rgba(0,0,0,0.2);\n    z-index: 9999;\n    font-size: 1.5rem;\n    transition: 0.3s;\n}\n#energi-dark-toggle:hover { transform: scale(1.1); }\n\n/* Global Smooth Scrolling */\nhtml { scroll-behavior: smooth !important; }\n\n/* Dark Mode Variables & Classes */\nbody.energi-dark-mode {\n    background-color: #1a202c !important;\n    color: #cbd5e0 !important;\n}\nbody.energi-dark-mode h1, body.energi-dark-mode h2, body.energi-dark-mode h3, body.energi-dark-mode a {\n    color: #f7fafc !important;\n}\nbody.energi-dark-mode .energi-page-bg {\n    background: #2d3748 !important;\n}\nbody.energi-dark-mode .energi-glass-card, body.energi-dark-mode .feature-card, body.energi-dark-mode .result-card {\n    background: rgba(0,0,0,0.5) !important;\n    border-color: #4a5568 !important;\n}\nbody.energi-dark-mode #masthead, body.energi-dark-mode .site-header {\n    background: rgba(26, 32, 44, 0.9) !important;\n    border-bottom-color: #4a5568 !important;\n}\nbody.energi-dark-mode .energi-input-group input {\n    background: rgba(0,0,0,0.3) !important;\n    color: white !important;\n    border-color: #4a5568 !important;\n}\nbody.energi-dark-mode .result-value { color: #f7fafc !important; }\nbody.energi-dark-mode .result-value.green { color: #00d084 !important; }\n</style>\n\n<script id=\"energi-premium-script\">\ndocument.addEventListener(\'DOMContentLoaded\', function() {\n    // 1. Inject Scroll Progress Bar\n    const progressBar = document.createElement(\'div\');\n    progressBar.id = \'energi-scroll-progress\';\n    document.body.prepend(progressBar);\n    \n    window.addEventListener(\'scroll\', () => {\n        const winScroll = document.body.scrollTop || document.documentElement.scrollTop;\n        const height = document.documentElement.scrollHeight - document.documentElement.clientHeight;\n        const scrolled = (winScroll / height) * 100;\n        progressBar.style.width = scrolled + \'%\';\n    });\n\n    // 2. Inject Dark Mode Toggle\n    const toggleBtn = document.createElement(\'div\');\n    toggleBtn.id = \'energi-dark-toggle\';\n    toggleBtn.innerHTML = \'🌙\';\n    document.body.appendChild(toggleBtn);\n    \n    // Check saved preference\n    if(localStorage.getItem(\'energiDarkMode\') === \'true\') {\n        document.body.classList.add(\'energi-dark-mode\');\n        toggleBtn.innerHTML = \'☀️\';\n    }\n\n    toggleBtn.addEventListener(\'click\', () => {\n        document.body.classList.toggle(\'energi-dark-mode\');\n        const isDark = document.body.classList.contains(\'energi-dark-mode\');\n        localStorage.setItem(\'energiDarkMode\', isDark);\n        toggleBtn.innerHTML = isDark ? \'☀️\' : \'🌙\';\n    });\n\n    // 3. Lazy Load All Content Images\n    const images = document.querySelectorAll(\'.wp-block-image img, .entry-content img\');\n    images.forEach(img => {\n        if(!img.hasAttribute(\'loading\')) {\n            img.setAttribute(\'loading\', \'lazy\');\n        }\n    });\n});\n</script>\n','סמארט-גריד ישראל','','publish','closed','closed','','%d7%a1{6d62aa24147240383df21bf87bf802e5f4d47310998c0216979dfdc0aea2a70','','','2026-06-19 00:15:24','2026-06-18 21:15:24','',308,'https://www.energi.co.il/%d7%90%d7{6d62aa24147240383df21bf87',0,'page','',0),
(359,2,'2026-06-19 00:12:47','2026-06-18 21:12:47','\n<style id=\"energi-premium-header\">\n/* --- BULLETPROOF PREMIUM HEADER STYLES --- */\nheader, #masthead, .site-header {\n    background: rgba(255, 255, 255, 0.95) !important;\n    backdrop-filter: blur(20px) !important;\n    -webkit-backdrop-filter: blur(20px) !important;\n    position: sticky !important;\n    top: 0 !important;\n    z-index: 9999 !important;\n    box-shadow: 0 4px 30px rgba(0, 0, 0, 0.08) !important;\n    padding: 15px 5% !important;\n    display: flex !important;\n    flex-direction: row-reverse !important;\n    justify-content: space-between !important;\n    align-items: center !important;\n    border-bottom: 1px solid rgba(0,0,0,0.05) !important;\n    width: 100% !important;\n    box-sizing: border-box !important;\n    margin: 0 !important;\n}\n\n/* Fix logo */\nheader a, .site-branding a, .custom-logo-link {\n    display: flex !important;\n    align-items: center !important;\n    text-decoration: none !important;\n}\nheader img, .custom-logo, .site-logo {\n    max-height: 55px !important;\n    width: auto !important;\n    margin: 0 !important;\n    padding: 0 !important;\n}\n\n/* Fix search bar */\nheader .searchform, .search-form {\n    display: flex !important;\n    flex-direction: row-reverse !important;\n    background: #f1f5f9 !important;\n    border-radius: 50px !important;\n    padding: 5px !important;\n    border: 1px solid #e2e8f0 !important;\n    align-items: center !important;\n    margin: 0 !important;\n}\nheader .searchform input[type=\"text\"], .search-field, input[type=\"search\"] {\n    border: none !important;\n    background: transparent !important;\n    outline: none !important;\n    padding: 8px 15px !important;\n    font-family: \'Heebo\', sans-serif !important;\n    width: 250px !important;\n    color: #334155 !important;\n}\nheader .searchform input[type=\"submit\"], .search-submit, button[type=\"submit\"] {\n    background: linear-gradient(135deg, #00d084, #009e60) !important;\n    color: white !important;\n    border: none !important;\n    border-radius: 50px !important;\n    padding: 8px 25px !important;\n    cursor: pointer !important;\n    font-family: \'Heebo\', sans-serif !important;\n    font-weight: bold !important;\n    transition: 0.3s !important;\n}\nheader .searchform input[type=\"submit\"]:hover {\n    box-shadow: 0 5px 15px rgba(0,208,132,0.4) !important;\n    transform: translateY(-1px) !important;\n}\n\n/* Hide theme default titles if they mess up layout */\n.site-title, .site-description { display: none !important; }\n</style>\n\n<style>\n/* Global resets to break out of the theme\'s narrow container */\nbody { margin: 0 !important; padding: 0 !important; background: #f8fafc !important; }\n#inner { width: 100% !important; max-width: 100% !important; margin: 0 !important; padding: 0 !important; background: transparent !important; border: none !important; box-shadow: none !important; }\n#contentarea { padding: 0 !important; margin: 0 !important; width: 100% !important; max-width: 100% !important; background: transparent !important; }\n#maincontent { width: 100% !important; float: none !important; padding: 0 !important; }\n#sidebar { display: none !important; }\n\n/* Hero Section */\n.hero-section {\n    background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);\n    position: relative;\n    overflow: hidden;\n    height: 75vh;\n    min-height: 500px;\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n    align-items: center;\n    text-align: center;\n    color: white;\n    padding: 0 20px;\n    font-family: \'Heebo\', sans-serif;\n    margin-top: -1px;\n}\n.hero-section::before {\n    content: \'\';\n    position: absolute;\n    top: 0; left: 0; right: 0; bottom: 0;\n    background: radial-gradient(circle at 50% 50%, rgba(0, 208, 132, 0.15) 0%, transparent 60%);\n    pointer-events: none;\n}\n.hero-section h1 {\n    font-size: 4.5rem;\n    font-weight: 800;\n    margin-bottom: 20px;\n    color: white;\n    z-index: 2;\n    line-height: 1.2;\n}\n.hero-section p {\n    font-size: 1.5rem;\n    margin-bottom: 40px;\n    max-width: 800px;\n    color: #cbd5e1;\n    z-index: 2;\n}\n.hero-buttons {\n    display: flex;\n    gap: 20px;\n    flex-wrap: wrap;\n    justify-content: center;\n    z-index: 2;\n}\n.btn-primary {\n    background: #00d084 !important;\n    color: white !important;\n    padding: 16px 45px !important;\n    border-radius: 50px !important;\n    font-size: 1.3rem !important;\n    font-weight: bold !important;\n    text-decoration: none !important;\n    transition: 0.3s !important;\n    box-shadow: 0 10px 25px rgba(0,208,132,0.3) !important;\n    border: none !important;\n}\n.btn-primary:hover { background: #009e60 !important; transform: translateY(-3px) !important; box-shadow: 0 15px 30px rgba(0,208,132,0.4) !important; }\n\n.btn-secondary {\n    background: rgba(255,255,255,0.1) !important;\n    backdrop-filter: blur(10px) !important;\n    color: white !important;\n    padding: 16px 45px !important;\n    border-radius: 50px !important;\n    font-size: 1.3rem !important;\n    font-weight: bold !important;\n    text-decoration: none !important;\n    border: 1px solid rgba(255,255,255,0.3) !important;\n    transition: 0.3s !important;\n}\n.btn-secondary:hover { background: rgba(255,255,255,0.2) !important; transform: translateY(-3px) !important; }\n\n/* Features Grid */\n.features-section {\n    padding: 100px 5%;\n    background: #f8fafc;\n    text-align: center;\n    direction: rtl;\n    position: relative;\n    z-index: 5;\n}\n.features-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\n    gap: 40px;\n    max-width: 1200px;\n    margin: 60px auto 0;\n}\n.feature-card {\n    background: white;\n    padding: 50px 30px;\n    border-radius: 24px;\n    box-shadow: 0 20px 40px rgba(0,0,0,0.04);\n    transition: 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n    border-bottom: 6px solid transparent;\n}\n.feature-card:hover { transform: translateY(-15px); border-bottom: 6px solid #00d084; box-shadow: 0 30px 60px rgba(0,0,0,0.08); }\n.feature-icon { font-size: 3.5rem; margin-bottom: 25px; display: inline-block; padding: 20px; background: #f1f5f9; border-radius: 50%; }\n.feature-card h3 { font-size: 1.8rem; margin-bottom: 15px; color: #1e293b; font-weight: 800; }\n.feature-card p { color: #64748b; line-height: 1.7; font-size: 1.1rem; }\n\n/* News Section Fixes */\n.news-section {\n    padding: 80px 5%;\n    background: white;\n    text-align: center;\n    direction: rtl;\n}\n.wp-block-latest-posts {\n    display: grid !important;\n    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)) !important;\n    gap: 30px !important;\n    max-width: 1200px !important;\n    margin: 0 auto !important;\n    padding: 0 !important;\n    list-style: none !important;\n}\n.wp-block-latest-posts li {\n    background: #f8fafc !important;\n    border-radius: 16px !important;\n    padding: 30px !important;\n    text-align: right !important;\n    box-shadow: 0 4px 15px rgba(0,0,0,0.03) !important;\n}\n.wp-block-latest-posts__post-title {\n    font-size: 1.4rem !important;\n    color: #1e293b !important;\n    font-weight: 800 !important;\n    text-decoration: none !important;\n    margin-bottom: 10px !important;\n    display: block !important;\n}\n.wp-block-latest-posts__post-title:hover { color: #00d084 !important; }\n.wp-block-latest-posts__post-date { color: #94a3b8 !important; font-size: 0.9rem !important; display: block !important; margin-bottom: 15px !important; }\n.wp-block-latest-posts__post-excerpt { color: #64748b !important; line-height: 1.6 !important; }\n\n/* Footer Fixes */\nfooter { width: 100% !important; background: #1e293b !important; color: white !important; padding: 40px 5% !important; text-align: center !important; }\nfooter a { color: #00d084 !important; }\n</style>\n\n<div class=\"hero-section\">\n    <h1>מהפכת האנרגיה מתחילה כאן</h1>\n    <p>הפורטל המוביל בישראל להשוואת מחירי התקנות סולאריות, עמדות טעינה וייעוץ חסכון בחשמל.</p>\n    <div class=\"hero-buttons\">\n        <a href=\"/solar-roi-calculator/\" class=\"btn-primary\">מחשבון סולארי ⚡</a>\n        <a href=\"/ev-savings-calculator/\" class=\"btn-secondary\">חיסכון רכב חשמלי 🚗</a>\n    </div>\n</div>\n\n<div class=\"features-section\">\n    <h2 style=\"font-size: 3rem; color: #1e293b; font-weight: 800;\">למה לבחור באנרגי?</h2>\n    <div class=\"features-grid\">\n        <div class=\"feature-card\">\n            <div class=\"feature-icon\">🔍</div>\n            <h3>אינדקס מתקינים</h3>\n            <p>מצאנו עבורך את המתקינים המורשים והמומלצים ביותר בישראל, ממוינים לפי ביקורות ומחירים.</p>\n            <a href=\"/installers-directory/\" style=\"color:#00d084; font-weight:bold; margin-top:15px; display:inline-block; text-decoration:none;\">למעבר לאינדקס ></a>\n        </div>\n        <div class=\"feature-card\">\n            <div class=\"feature-icon\">💰</div>\n            <h3>מחשבוני חיסכון</h3>\n            <p>גלה בדיוק כמה תוכל לחסוך בכל חודש על חשבון החשמל והדלק שלך בעזרת הכלים החכמים שלנו.</p>\n        </div>\n        <div class=\"feature-card\">\n            <div class=\"feature-icon\">🤝</div>\n            <h3>3 הצעות מחיר</h3>\n            <p>ממלאים טופס קצר ומקבלים עד 3 הצעות מחיר משתלמות ממתקינים באזור המגורים שלך.</p>\n        </div>\n    </div>\n</div>\n\n<div class=\"news-section\">\n    <h2 style=\"font-size: 2.5rem; color: #1e293b; margin-bottom: 40px; font-weight: 800;\">חדשות וכתבות</h2>\n    <!-- wp:latest-posts {\"displayPostDate\":true,\"displayFeaturedImage\":false,\"columns\":3,\"displayPostContent\":true,\"displayPostContentRadio\":\"excerpt\",\"excerptLength\":15} /-->\n</div>\n','עמוד הבית - הפורטל המרכזי','','publish','closed','closed','','%d7%a2{6d62aa24147240383df21bf87bf802e5f4d47310998c0216979dfdc0aea2a70','','','2026-06-19 00:20:36','2026-06-18 21:20:36','',0,'https://www.energi.co.il/%d7%a2%d7{6d62aa24147240383df21bf87',0,'page','',0),
(398,1,'2026-06-19 00:13:14','0000-00-00 00:00:00','Thank you for reading this post, don\'t forget to subscribe!','Display a message after the 1st paragraph of posts','','draft','closed','closed','','','','','2026-06-19 00:13:14','0000-00-00 00:00:00','',0,'https://www.energi.co.il/?post_type=wpcode&p=398',0,'wpcode','',0),
(399,1,'2026-06-19 00:13:14','0000-00-00 00:00:00','add_action(\'admin_init\', function () {\r\n    // Redirect any user trying to access comments page\r\n    global $pagenow;\r\n    \r\n    if ($pagenow === \'edit-comments.php\') {\r\n        wp_safe_redirect(admin_url());\r\n        exit;\r\n    }\r\n\r\n    // Remove comments metabox from dashboard\r\n    remove_meta_box(\'dashboard_recent_comments\', \'dashboard\', \'normal\');\r\n\r\n    // Disable support for comments and trackbacks in post types\r\n    foreach (get_post_types() as $post_type) {\r\n        if (post_type_supports($post_type, \'comments\')) {\r\n            remove_post_type_support($post_type, \'comments\');\r\n            remove_post_type_support($post_type, \'trackbacks\');\r\n        }\r\n    }\r\n});\r\n\r\n// Close comments on the front-end\r\nadd_filter(\'comments_open\', \'__return_false\', 20, 2);\r\nadd_filter(\'pings_open\', \'__return_false\', 20, 2);\r\n\r\n// Hide existing comments\r\nadd_filter(\'comments_array\', \'__return_empty_array\', 10, 2);\r\n\r\n// Remove comments page in menu\r\nadd_action(\'admin_menu\', function () {\r\n    remove_menu_page(\'edit-comments.php\');\r\n});\r\n\r\n// Remove comments links from admin bar\r\nadd_action(\'init\', function () {\r\n    if (is_admin_bar_showing()) {\r\n        remove_action(\'admin_bar_menu\', \'wp_admin_bar_comments_menu\', 60);\r\n    }\r\n});','Completely Disable Comments','','draft','closed','closed','','','','','2026-06-19 00:13:14','0000-00-00 00:00:00','',0,'https://www.energi.co.il/?post_type=wpcode&p=399',0,'wpcode','',0),
(495,1,'2026-09-03 09:37:29','2026-09-03 09:37:29','<h2>1. כללי והתחייבות להגנת הפרטיות</h2><p>אתר energi.co.il מופעל ומנוהל על ידי האב מערכות מתקדמות בע\"מ. האתר מייחס חשיבות עליונה להגנה על פרטיות המשתמשים ופועל בהתאם להוראות חוק הגנת הפרטיות, התשמ\"א-1981 ותקנות הגנת הפרטיות (אבטחת מידע), התשע\"ז-2017.</p><h2>2. איסוף מידע ומטרותיו</h2><p>המידע הנאסף בטפסי האתר (כגון שם, טלפון, דואר אלקטרוני ופרטי פנייה) נמסר על ידי המשתמש מרצונו החופשי. המידע משמש בלבד לצורך מתן השירות המבוקש, חזרה לפונים והתאמת הצעות מחיר ממתקינים מורשים.</p><h2>3. אבטחת מידע והקשחת סייבר</h2><p>האתר מיושם בסביבת ענן מאובטחת העומדת בתקני אבטחת המידע המחמירים ביותר, כולל הצפנת SSL/TLS, חסימת ניסיונות גישה לא מורשים ומחיקה תקופתית של נתוני זמניים (Transients).</p><h2>4. זכויות המשתמש</h2><p>לפי סעיף 13 לחוק הגנת הפרטיות, כל משתמש זכאי לעיין במידע המוחזק עליו במאגר הנתונים, ולבקש תיקון או מחיקה של מידע במידה ואינו נכון או מעודכן. לפניות בנושא פרטיות ניתן ליצור קשר בכתובת: privacy@energi.co.il.</p>','מדיניות פרטיות ותקנון תנאי שימוש (תשע\"ז-2017)','','publish','closed','closed','','privacy-policy','','','2026-09-03 09:37:29','2026-09-03 09:37:29','',0,'http://localhost:8085/?page_id=495',0,'page','',0),
(496,1,'2026-09-03 14:07:52','2026-09-03 14:07:52','','בלוג ומדריכים 2026','','publish','closed','closed','','blog','','','2026-09-03 14:07:52','2026-09-03 14:07:52','',0,'http://localhost:8085/?page_id=500',0,'page','',0);
INSERT INTO `wpw4_snippets` VALUES
(1,'Make upload filenames lowercase','Makes sure that image and file uploads have lowercase filenames.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_filter( \'sanitize_file_name\', \'mb_strtolower\' );','sample, media','global',0,10,0,'2026-07-21 16:14:48',1,NULL),
(2,'Disable admin bar','Turns off the WordPress admin bar for everyone except administrators.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );','sample, admin-bar','front-end',0,10,0,'2026-07-21 16:14:48',1,NULL),
(3,'Allow smilies','Allows smiley conversion in obscure places.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' );','sample','global',0,10,0,'2026-07-21 16:14:48',1,NULL),
(4,'Current year','Shortcode for inserting the current year into a post or page..\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','<?php echo date( \'Y\' ); ?>','sample, dates','content',0,10,0,'2026-07-21 16:14:48',1,NULL),
(5,'HUB Migrate Export (temp)','','add_action(\'rest_api_init\', function () {\n  register_rest_route(\'hub-migrate/v1\', \'/export\', array(\n    \'methods\' => \'POST\',\n    \'permission_callback\' => function () { return current_user_can(\'manage_options\'); },\n    \'callback\' => \'hub_migrate_export_cb\',\n  ));\n});\nif (!function_exists(\'hub_migrate_export_cb\')) {\nfunction hub_migrate_export_cb() {\n  if (!class_exists(\'ZipArchive\')) {\n    return new WP_Error(\'no_zip\', \'ZipArchive not available\', array(\'status\' => 500));\n  }\n  global $wpdb;\n  $upload = wp_upload_dir();\n  if (!empty($upload[\'error\'])) {\n    return new WP_Error(\'upload_dir\', $upload[\'error\'], array(\'status\' => 500));\n  }\n  $token = \'ff3e51b424a65c1c\';\n  $dir = trailingslashit($upload[\'basedir\']) . \'hub-migrate-\' . $token;\n  $urlbase = trailingslashit($upload[\'baseurl\']) . \'hub-migrate-\' . $token;\n  if (!wp_mkdir_p($dir)) {\n    return new WP_Error(\'mkdir\', \'Cannot create export dir\', array(\'status\' => 500));\n  }\n  $sql_path = $dir . \'/database.sql\';\n  $zip_path = $dir . \'/files.zip\';\n  $fh = fopen($sql_path, \'wb\');\n  if (!$fh) return new WP_Error(\'sql\', \'Cannot write SQL\', array(\'status\' => 500));\n  // Double-quoted PHP strings so \\n becomes real newlines (single-quoted \\n was written\n  // literally and broke CREATE TABLE on MySQL import).\n  fwrite($fh, \"-- HUB migrate dump\\nSET NAMES utf8mb4;\\nSET SESSION sql_mode=\'ALLOW_INVALID_DATES,NO_ENGINE_SUBSTITUTION\';\\n\\n\");\n  $tables = $wpdb->get_col(\'SHOW TABLES\');\n  foreach ((array) $tables as $table) {\n    $table = preg_replace(\'/[^A-Za-z0-9_]/\', \'\', (string) $table);\n    if ($table === \'\') continue;\n    $create = $wpdb->get_row(\'SHOW CREATE TABLE `\' . $table . \'`\', ARRAY_N);\n    if (!$create) continue;\n    fwrite($fh, \"DROP TABLE IF EXISTS `\" . $table . \"`;\\n\" . $create[1] . \";\\n\\n\");\n    $offset = 0;\n    $chunk = 200;\n    while (true) {\n      $rows = $wpdb->get_results(\'SELECT * FROM `\' . $table . \'` LIMIT \' . intval($chunk) . \' OFFSET \' . intval($offset), ARRAY_A);\n      if (!$rows) break;\n      foreach ($rows as $row) {\n        $cols = array();\n        $vals = array();\n        foreach ($row as $c => $v) {\n          $cols[] = \'`\' . str_replace(\'`\', \'\', $c) . \'`\';\n          if (is_null($v)) $vals[] = \'NULL\';\n          else $vals[] = \"\'\" . esc_sql((string) $v) . \"\'\";\n        }\n        fwrite($fh, \"INSERT INTO `\" . $table . \"` (\" . implode(\',\', $cols) . \") VALUES (\" . implode(\',\', $vals) . \");\\n\");\n      }\n      $offset += $chunk;\n      if (count($rows) < $chunk) break;\n    }\n    fwrite($fh, \"\\n\");\n  }\n  fclose($fh);\n  $zip = new ZipArchive();\n  if (true !== $zip->open($zip_path, ZipArchive::CREATE | ZipArchive::OVERWRITE)) {\n    return new WP_Error(\'zip_open\', \'Cannot create zip\', array(\'status\' => 500));\n  }\n  $root = rtrim(ABSPATH, \'/\\\\\');\n  $skip_needles = array(\'hub-migrate-\', \'ai1wm-backups\', \'/cache/\', \'wflogs\', \'.git\');\n  $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::SELF_FIRST);\n  foreach ($iterator as $file) {\n    $path = $file->getPathname();\n    $rel = substr($path, strlen($root) + 1);\n    if ($rel === false || $rel === \'\') continue;\n    $norm = str_replace(\'\\\\\', \'/\', $rel);\n    $lower = strtolower($norm);\n    $bad = false;\n    foreach ($skip_needles as $s) {\n      if (strpos($lower, $s) !== false) { $bad = true; break; }\n    }\n    if ($bad) continue;\n    if ($file->isDir()) { $zip->addEmptyDir($norm); continue; }\n    if ($file->getSize() > 120 * 1024 * 1024) continue;\n    $zip->addFile($path, $norm);\n  }\n  $zip->close();\n  return array(\n    \'ok\' => true,\n    \'token\' => $token,\n    \'sql_url\' => $urlbase . \'/database.sql\',\n    \'archive_url\' => $urlbase . \'/files.zip\',\n    \'sql_bytes\' => @filesize($sql_path),\n    \'archive_bytes\' => @filesize($zip_path),\n  );\n}\n}','','global',0,10,1,'2026-07-21 16:14:48',1,NULL);
